      { id: '11-m-25', english: 'successful', vietnamese: 'thành công, thành đạt', antonym: 'unsuccessful', exampleEn: 'The campaign was highly successful.', exampleVi: 'Chiến dịch đã rất thành công.' },
      { id: '11-m-26', english: 'hold', vietnamese: 'cầm, giữ, tổ chức', antonym: 'release', exampleEn: 'They will hold a press conference today.', exampleVi: 'Họ sẽ tổ chức một cuộc họp báo hôm nay.' },
      { id: '11-m-27', english: 'advance', vietnamese: 'thành tựu, sự tiến bộ, sự thăng tiến', antonym: 'retreat', exampleEn: 'Medical advances have saved many lives.', exampleVi: 'Những tiến bộ y học đã cứu sống nhiều mạng người.' },
      { id: '11-m-28', english: 'reliable', vietnamese: 'đáng tin cậy', antonym: 'unreliable', exampleEn: 'We need a reliable delivery service.', exampleVi: 'Chúng ta cần một dịch vụ giao hàng đáng tin cậy.' },
      { id: '11-m-29', english: 'quality', vietnamese: 'chất lượng; có chất lượng cao', antonym: '-', exampleEn: 'We never compromise on product quality.', exampleVi: 'Chúng tôi không bao giờ thỏa hiệp về chất lượng sản phẩm.' },
      { id: '11-m-30', english: 'domestic', vietnamese: 'trong nước, nội địa, (thuộc) việc nhà', antonym: 'international', exampleEn: 'Domestic flights depart from Terminal 2.', exampleVi: 'Các chuyến bay nội địa khởi hành từ Nhà ga số 2.' },
      { id: '11-m-31', english: 'development', vietnamese: 'sự phát triển, sự tiến triển', antonym: 'decline', exampleEn: 'Research and development is crucial.', exampleVi: 'Nghiên cứu và phát triển là rất quan trọng.' },
      { id: '11-m-32', english: 'availability', vietnamese: 'sự có sẵn, có thể mua được, sự có hiệu lực', antonym: 'unavailability', exampleEn: 'Please check the availability of the room.', exampleVi: 'Vui lòng kiểm tra tình trạng trống của căn phòng.' },
      { id: '11-m-33', english: 'update', vietnamese: 'sự cập nhật, sự nâng cấp; cập nhật, nâng cấp', antonym: '-', exampleEn: 'I will send you an update tomorrow.', exampleVi: 'Tôi sẽ gửi cho bạn bản cập nhật vào ngày mai.' },
      { id: '11-m-34', english: 'accurate', vietnamese: 'đúng, chính xác', antonym: 'inaccurate', exampleEn: 'The financial report must be accurate.', exampleVi: 'Báo cáo tài chính phải chính xác.' },
      { id: '11-m-35', english: 'complicated', vietnamese: 'phức tạp, rắc rối', antonym: 'simple', exampleEn: 'The instructions are too complicated.', exampleVi: 'Các hướng dẫn quá phức tạp.' },
      { id: '11-m-36', english: 'accomplished', vietnamese: 'đã hoàn thành, trọn vẹn, hoàn hảo, có tài năng', antonym: 'unaccomplished', exampleEn: 'She is an accomplished pianist.', exampleVi: 'Cô ấy là một nghệ sĩ piano tài năng.' },
      { id: '11-m-37', english: 'inquiry', vietnamese: 'sự điều tra, sự thẩm vấn, câu hỏi, sự đòi hỏi', antonym: '-', exampleEn: 'We received an inquiry about the price.', exampleVi: 'Chúng tôi đã nhận được một yêu cầu báo giá.' },
      { id: '11-m-38', english: 'indication', vietnamese: 'biểu hiện, dấu hiệu', antonym: '-', exampleEn: 'There is no indication of a problem.', exampleVi: 'Không có dấu hiệu nào của vấn đề.' },
      { id: '11-m-39', english: 'manufacturer', vietnamese: 'nhà sản xuất, chủ xưởng, chủ xí nghiệp', antonym: 'consumer', exampleEn: 'The manufacturer offers a one-year warranty.', exampleVi: 'Nhà sản xuất cung cấp bảo hành một năm.' },
      { id: '11-m-40', english: 'compatible', vietnamese: 'tương thích, thích hợp', antonym: 'incompatible', exampleEn: 'This software is compatible with Mac.', exampleVi: 'Phần mềm này tương thích với Mac.' },
      { id: '11-m-41', english: 'superior', vietnamese: 'cao, cao cấp, tốt hơn', antonym: 'inferior', exampleEn: 'Our product is of superior quality.', exampleVi: 'Sản phẩm của chúng tôi có chất lượng vượt trội.' },
      { id: '11-m-42', english: 'absolute', vietnamese: 'tuyệt đối, hoàn toàn, thuần túy', antonym: 'partial', exampleEn: 'I have absolute confidence in her.', exampleVi: 'Tôi hoàn toàn tin tưởng vào cô ấy.' },
      { id: '11-m-43', english: 'broaden', vietnamese: 'mở rộng', antonym: 'narrow', exampleEn: 'Travel helps to broaden your mind.', exampleVi: 'Du lịch giúp mở rộng tâm trí của bạn.' },
      { id: '11-m-44', english: 'corrosion', vietnamese: 'sự ăn mòn', antonym: '-', exampleEn: 'The pipe was damaged by corrosion.', exampleVi: 'Đường ống đã bị hỏng do ăn mòn.' }
